import { TestBed } from '@angular/core/testing';
import { describe, it, expect, beforeEach } from 'vitest';
import { WatchlistStore } from '../app/watchlist-store';

function movie(id: number, title: string): { id: number; title: string; release_date: string; poster_path: string | null; overview: string } {
  return { id, title, release_date: '2024-01-01', poster_path: null, overview: 'A movie.' };
}

describe('WatchlistStore.clearWatched', () => {
  let store: WatchlistStore;

  beforeEach(() => {
    localStorage.clear();
    TestBed.configureTestingModule({ providers: [WatchlistStore] });
    store = TestBed.inject(WatchlistStore);
  });

  it('removes every watched item and keeps the unwatched ones', () => {
    store.add(movie(1, 'Watched one'));
    store.add(movie(2, 'Unwatched one'));
    store.add(movie(3, 'Watched two'));
    store.toggleWatched(1);
    store.toggleWatched(3);

    const removed = store.clearWatched();

    expect(removed).toBe(2);
    expect(store.items().map((m) => m.id).sort((a, b) => a - b)).toEqual([2]);
    expect(store.count()).toBe(1);
    expect(store.watchedCount()).toBe(0);
  });

  it('returns 0 and keeps the list when nothing is watched', () => {
    store.add(movie(1, 'Unwatched one'));
    store.add(movie(2, 'Unwatched two'));

    expect(store.clearWatched()).toBe(0);
    expect(store.items().map((m) => m.id).sort((a, b) => a - b)).toEqual([1, 2]);
    expect(store.count()).toBe(2);
  });

  it('is a no-op on an empty watchlist', () => {
    expect(store.clearWatched()).toBe(0);
    expect(store.count()).toBe(0);
    expect(store.items()).toEqual([]);
  });

  it('persists the cleared watchlist', () => {
    store.add(movie(1, 'Watched one'));
    store.add(movie(2, 'Unwatched one'));
    store.toggleWatched(1);
    store.clearWatched();

    TestBed.resetTestingModule();
    TestBed.configureTestingModule({ providers: [WatchlistStore] });
    const reloaded = TestBed.inject(WatchlistStore);

    expect(reloaded.items().map((m) => m.id)).toEqual([2]);
    expect(reloaded.watchedCount()).toBe(0);
  });
});
```

