import { TestBed } from '@angular/core/testing';
import { beforeEach, describe, expect, it } from 'vitest';
import type { TmdbMovie } from '../app/movie';
import { WatchlistStore } from '../app/watchlist-store';

function movie(id: number, title: string): TmdbMovie {
  return {
    id,
    title,
    release_date: '2024-01-01',
    poster_path: null,
    overview: 'A movie.',
  };
}

const storedText = (): string => {
  const parts: string[] = [];
  for (const storage of [localStorage, sessionStorage]) {
    for (let i = 0; i < storage.length; i++) {
      const key = storage.key(i);
      if (key !== null) parts.push(storage.getItem(key) ?? '');
    }
  }
  return parts.join(' ');
};

describe('WatchlistStore.clearWatched()', () => {
  let store: WatchlistStore;

  beforeEach(() => {
    localStorage.clear();
    sessionStorage.clear();
    TestBed.configureTestingModule({ providers: [WatchlistStore] });
    store = TestBed.inject(WatchlistStore);
  });

  it('removes every watched item, keeps unwatched ones, and returns the count', () => {
    store.add(movie(1, 'Alpha'));
    store.add(movie(2, 'Beta'));
    store.add(movie(3, 'Gamma'));
    store.toggleWatched(1);
    store.toggleWatched(3);

    const removed = store.clearWatched();

    expect(removed).toBe(2);
    expect(store.items().map((m) => m.id).sort((a, b) => a - b)).toEqual([2]);
    expect(store.count()).toBe(1);
    expect(store.watchedCount()).toBe(0);
  });

  it('keeps the watchlist intact when nothing is watched', () => {
    store.add(movie(1, 'Alpha'));
    store.add(movie(2, 'Beta'));

    expect(store.clearWatched()).toBe(0);
    expect(store.items().map((m) => m.id).sort((a, b) => a - b)).toEqual([1, 2]);
    expect(store.count()).toBe(2);
    expect(store.watchedCount()).toBe(0);
  });

  it('is a safe no-op on an empty watchlist', () => {
    expect(store.clearWatched()).toBe(0);
    expect(store.items()).toEqual([]);
    expect(store.count()).toBe(0);
  });

  it('persists the cleared watchlist', () => {
    store.add(movie(1, 'Alpha'));
    store.add(movie(2, 'Beta'));
    store.toggleWatched(1);
    store.clearWatched();

    const raw = storedText();
    expect(raw).toContain('Beta');
    expect(raw).not.toContain('Alpha');
  });
});

