import { describe, it, expect, beforeEach } from 'vitest';
import { WatchlistStore } from '../app/watchlist-store';
import { TmdbMovie } from '../app/movie';

function tmdb(id: number, title: string): TmdbMovie {
  return { id, title, release_date: '2024-05-05', poster_path: null, overview: 'plot' };
}

function titles(store: WatchlistStore): string[] {
  return store.items().map((m) => m.title);
}

/** Everything the app has persisted, regardless of the storage key used. */
function storageDump(): string {
  const parts: string[] = [];
  for (let i = 0; i < localStorage.length; i++) {
    const key = localStorage.key(i);
    if (key === null) continue;
    parts.push(`${key}=${localStorage.getItem(key) ?? ''}`);
  }
  return parts.join('\n');
}

describe('WatchlistStore.clearWatched()', () => {
  beforeEach(() => {
    localStorage.clear();
  });

  it('removes every watched item, keeps unwatched ones, and returns the count', () => {
    const store = new WatchlistStore();
    store.add(tmdb(1, 'Alpha'));
    store.add(tmdb(2, 'Beta'));
    store.add(tmdb(3, 'Gamma'));
    store.toggleWatched(1);
    store.toggleWatched(3);

    const removed = store.clearWatched();

    expect(removed).toBe(2);
    expect(titles(store)).toEqual(['Beta']);
    expect(store.count()).toBe(1);
    expect(store.watchedCount()).toBe(0);
  });

  it('keeps the watchlist intact when nothing is watched', () => {
    const store = new WatchlistStore();
    store.add(tmdb(1, 'Alpha'));
    store.add(tmdb(2, 'Beta'));

    const removed = store.clearWatched();

    expect(removed).toBe(0);
    expect(titles(store)).toEqual(['Alpha', 'Beta']);
    expect(store.watchedCount()).toBe(0);
  });

  it('is a safe no-op on an empty watchlist', () => {
    const store = new WatchlistStore();

    expect(store.clearWatched()).toBe(0);
    expect(store.items()).toEqual([]);
    expect(store.count()).toBe(0);
    expect(store.watchedCount()).toBe(0);
  });

  it('persists the cleared watchlist', () => {
    const store = new WatchlistStore();
    store.add(tmdb(1, 'Alpha'));
    store.add(tmdb(2, 'Beta'));
    store.add(tmdb(3, 'Gamma'));
    store.toggleWatched(1);
    store.toggleWatched(3);

    expect(store.clearWatched()).toBe(2);

    const dump = storageDump();
    expect(dump).toContain('Beta');
    expect(dump).not.toContain('Alpha');

    const reloaded = new WatchlistStore();
    expect(titles(reloaded)).toEqual(['Beta']);
    expect(reloaded.count()).toBe(1);
    expect(reloaded.watchedCount()).toBe(0);
  });
});
```

