    expect(dump).not.toContain('Watched To Remove');

    TestBed.resetTestingModule();
    TestBed.configureTestingModule({ providers: [WatchlistStore] });
    const fresh = TestBed.inject(WatchlistStore);

    expect(itemIds(fresh)).toEqual([21]);
    expect(fresh.items()[0].watched).toBe(false);
  });
});
