    store.add(movie(10, 'Plain Alpha'));
    store.add(movie(11, 'Plain Beta'));

    const removed = store.clearWatched();

    expect(removed).toBe(0);
    expect(itemIds(store)).toEqual([10, 11]);
    expect(store.count()).toBe(2);
  });

